import { MemoryStore } from "../src/store.ts";
import { ValidationError } from "../src/validate.ts";

describe("MemoryStore series cap", () => {
  it("rejects a new series once the store is at its series cap", () => {
    const store = new MemoryStore(100, 2);
    store.put({ series: "a", value: 1, at: 1 });
    store.put({ series: "b", value: 1, at: 1 });

    assert.throws(
      () => store.put({ series: "c", value: 1, at: 1 }),
      ValidationError,
    );
    assert.deepEqual(store.series(), ["a", "b"]);
  });

  it("keeps already-tracked series writable at the cap", () => {
    const store = new MemoryStore(100, 1);
    store.put({ series: "a", value: 1, at: 1 });
    store.put({ series: "a", value: 2, at: 2 });

    assert.deepEqual(store.series(), ["a"]);
    assert.equal(store.size(), 2);
  });

  it("refuses a non-positive series cap", () => {
    assert.throws(() => new MemoryStore(100, 0), RangeError);
  });
});

