import { ConfigError, DEFAULT_CONFIG, loadConfig } from "../src/config.ts";

describe("loadConfig maxSeries", () => {
  it("falls back to the default when unset", () => {
    const config = loadConfig({});
    assert.equal(config.maxSeries, DEFAULT_CONFIG.maxSeries);
  });

  it("reads ROLLUP_MAX_SERIES when present", () => {
    const config = loadConfig({ ROLLUP_MAX_SERIES: "5" });
    assert.equal(config.maxSeries, 5);
  });

  it("throws ConfigError naming the key on a bad value", () => {
    try {
      loadConfig({ ROLLUP_MAX_SERIES: "not-a-number" });
      assert.fail("expected a ConfigError");
    } catch (error) {
      assert.ok(error instanceof ConfigError);
      assert.equal(error.key, "ROLLUP_MAX_SERIES");
    }
  });
});

