describe("Router ingest series cap", () => {
  it("responds 400 naming the series field once the cap is reached", () => {
    const store = new MemoryStore(DEFAULT_CONFIG.maxSamples, 1);
    const router = createRouter(store, DEFAULT_CONFIG, new FixedClock(1_000));

    const first = router.dispatch("POST", "/samples", "a 1\n");
    assert.equal(first.status, 202);

    const second = router.dispatch("POST", "/samples", "b 1\n");
    assert.equal(second.status, 400);
    assert.match(second.body, /series:/);
    assert.match(second.body, /accepted 0/);
  });
});

