/**
 * Durability for the sample store: one append-only, newline-delimited JSON
 * file per store. Every accepted sample is appended before the write that
 * admitted it returns, so a process restart can replay exactly what was
 * accepted since the log's last compaction.
 */

import {
  appendFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  renameSync,
  writeFileSync,
} from "node:fs";
import { dirname } from "node:path";

import type { Sample } from "./validate.ts";

export class SampleLog {
  private readonly path: string;

  constructor(path: string) {
    this.path = path;
    const dir = dirname(path);
    if (dir !== "." && dir !== "") mkdirSync(dir, { recursive: true });
  }

  /** Durably record one sample, appending to the log. */
  append(sample: Sample): void {
    appendFileSync(this.path, `${JSON.stringify(sample)}\n`);
  }

  /**
   * Every sample durably recorded, oldest first. A trailing line a crash cut
   * short mid-write is not valid JSON and is dropped, along with anything
   * after it — no partial record is ever replayed.
   */
  replay(): Sample[] {
    if (!existsSync(this.path)) return [];
    const lines = readFileSync(this.path, "utf8").split("\n");
    const samples: Sample[] = [];
    for (const line of lines) {
      if (line.trim() === "") continue;
      let parsed: unknown;
      try {
        parsed = JSON.parse(line);
      } catch {
        break;
      }
      samples.push(parsed as Sample);
    }
    return samples;
  }

  /**
   * Atomically replace the log's contents with exactly `samples` — the
   * durability equivalent of the store's own retention pruning, so the log
   * does not grow without bound over the life of the process.
   */
  compact(samples: Sample[]): void {
    const body = samples.map((sample) => JSON.stringify(sample)).join("\n");
    const tmpPath = `${this.path}.tmp`;
    writeFileSync(tmpPath, body.length > 0 ? `${body}\n` : "");
    renameSync(tmpPath, this.path);
  }
}

