export function createService(
  config: Config = loadConfig(),
  clock: Clock = new SystemClock(),
  log: SampleLog = new SampleLog(config.dataFile),
): Service {
  const store = new MemoryStore(config.maxSamples, config.maxSeries);
  for (const sample of log.replay()) {
    try {
      store.put(sample);
    } catch {
      // No longer fits the store's current caps (e.g. maxSeries shrank since
      // this sample was recorded) — the log stays the record of truth, but a
      // sample that would not be admitted live today is not force-fed back in.
    }
  }

  const queue = new IngestQueue(config.maxSamples);
  const router = createRouter(store, config, clock, log);

  return {
    config,
    store,
    queue,
    router,
    tick(): void {
      for (const sample of queue.drain()) {
        store.put(sample);
        log.append(sample);
      }
      store.prune(clock.now() - config.retentionMs);
      log.compact(store.all());
    },
  };
}

