import assert from "node:assert/strict";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, it } from "node:test";

import { FixedClock } from "../src/clock.ts";
import { createService } from "../src/index.ts";

function tempDataFile(): string {
  const dir = mkdtempSync(join(tmpdir(), "stonefly-"));
  return join(dir, "samples.log");
}

describe("createService wiring", () => {
  it("passes config.maxSeries into the store's series cap", () => {
    const service = createService(
      {
        windowMs: 1_000,
        maxSamples: 100,
        maxSeries: 1,
        retentionMs: 60_000,
        dataFile: tempDataFile(),
      },
      new FixedClock(1_000),
    );

    service.store.put({ series: "a", value: 1, at: 1_000 });
    assert.throws(() => service.store.put({ series: "b", value: 1, at: 1_000 }));
  });

  it("restores samples recorded before a restart", () => {
    const dataFile = tempDataFile();
    const config = {
      windowMs: 1_000,
      maxSamples: 100,
      maxSeries: 10,
      retentionMs: 60_000,
      dataFile,
    };

    const before = createService(config, new FixedClock(1_000));
    before.router.dispatch("POST", "/samples", "cpu.load 0.5 1000\n");
    before.router.dispatch("POST", "/samples", "cpu.load 0.7 1500\n");

    const after = createService(config, new FixedClock(2_000));
    assert.deepEqual(
      after.store.range("cpu.load", 0, 2_000).map((s) => s.value),
      [0.5, 0.7],
    );
  });
});

