import assert from "node:assert/strict";
import { appendFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, it } from "node:test";

import { SampleLog } from "../src/persistence.ts";

function tempPath(): string {
  const dir = mkdtempSync(join(tmpdir(), "stonefly-"));
  return join(dir, "samples.log");
}

describe("SampleLog", () => {
  it("replays an empty result when nothing was ever written", () => {
    const log = new SampleLog(tempPath());
    assert.deepEqual(log.replay(), []);
  });

  it("replays appended samples in order", () => {
    const log = new SampleLog(tempPath());
    log.append({ series: "a", value: 1, at: 1 });
    log.append({ series: "a", value: 2, at: 2 });

    assert.deepEqual(log.replay(), [
      { series: "a", value: 1, at: 1 },
      { series: "a", value: 2, at: 2 },
    ]);
  });

  it("drops a truncated trailing line rather than failing replay", () => {
    const path = tempPath();
    const log = new SampleLog(path);
    log.append({ series: "a", value: 1, at: 1 });
    appendFileSync(path, '{"series":"a","value":2,"at"');

    assert.deepEqual(log.replay(), [{ series: "a", value: 1, at: 1 }]);
  });

  it("compact atomically replaces the log's contents", () => {
    const log = new SampleLog(tempPath());
    log.append({ series: "a", value: 1, at: 1 });
    log.append({ series: "a", value: 2, at: 2 });
    log.append({ series: "a", value: 3, at: 3 });

    log.compact([{ series: "a", value: 3, at: 3 }]);

    assert.deepEqual(log.replay(), [{ series: "a", value: 3, at: 3 }]);
  });

  it("compact to empty leaves a replayable, empty log", () => {
    const log = new SampleLog(tempPath());
    log.append({ series: "a", value: 1, at: 1 });

    log.compact([]);

    assert.deepEqual(log.replay(), []);
  });

  it("creates the parent directory on construction", () => {
    const dir = mkdtempSync(join(tmpdir(), "stonefly-"));
    const nested = join(dir, "nested", "sub", "samples.log");
    const log = new SampleLog(nested);
    log.append({ series: "a", value: 1, at: 1 });

    assert.deepEqual(log.replay(), [{ series: "a", value: 1, at: 1 }]);
  });
});

